const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const items = $input.all();

const requiredFields = [
  "Ticket_ID",
  "Customer_ID",
  "Customer_Name",
  "Customer_Email",
  "Subject",
  "Conversation",
  "Created_Date",
  "Current_Status"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  const createdDate =
    new Date(data.Created_Date);

  const dateValid =
    !isNaN(createdDate.getTime());

  if (
    missingFields.length === 0 &&
    dateValid
  ) {

    validItems.push({
      ...data
    });

  } else {

    invalidItems.push({
      ticket_id:
        data.Ticket_ID || "Unknown",

      missing_fields:
        missingFields
    });
  }
}

return [
  {
    json: {

      data_valid:
        invalidItems.length === 0,

      total_tickets:
        items.length,

      valid_tickets:
        validItems.length,

      invalid_tickets:
        invalidItems.length,

      invalid_details:
        invalidItems,

      ticket_data:
        validItems
    }
  }
];

const tickets = $json.ticket_data;

const results = [];

for (const ticket of tickets) {

  const conversation =
    String(ticket.Conversation);

  const wordCount =
    conversation
      .trim()
      .split(/\s+/)
      .filter(Boolean)
      .length;

  let complexity;

  if (wordCount > 500) {
    complexity = "HIGH";
  } else if (wordCount > 200) {
    complexity = "MEDIUM";
  } else {
    complexity = "LOW";
  }

  results.push({

    ...ticket,

    Conversation_Length:
      wordCount,

    Conversation_Complexity:
      complexity
  });
}

return [
  {
    json: {
      prepared_tickets:
        results
    }
  }
];

